#!/usr/bin/env zsh

function __rg_bootstrap () {
  if [ "$(mise which -q rg 2> /dev/null)" ]; then
    local RG_COMMAND=$(mise which rg)

    if [ ! -f "${ZSH_COMPLETION_FOLDER}/_rg.zsh" ]; then
      rg --generate complete-zsh > "${ZSH_COMPLETION_FOLDER}/_rg.zsh"
    fi
  fi
}

__rg_bootstrap "$@"

{{- $context := .context -}}
{{- if not (get . "disabled") }}
{{- includeTemplate "zshrc/helpers/h3" "Zinit Plugins - ripgrep" }}

## Setup ripgrep - extends grep command
## https://github.com/BurntSushi/ripgrep
zinit ice {{- if hasKey . "lazy" | ternary (get . "lazy") true }} wait lucid{{- end }} as"command" \
  from"gh-r" bpick"ripgrep-*.tar.gz" pick"ripgrep-*/rg" \
  atclone"ripgrep-*/rg --generate complete-zsh > _rg" atpull"%atclone"
zinit {{ get . "act" | default "light" }} BurntSushi/ripgrep

{{ end -}}

#!zsh

if (( ${+commands[rg]} )); then
  (
    setopt extendedglob

    if ! [[ -e ~/.zsh/functions/_rg(#qN.mh+24) ]]; then
      {
        command rg --generate=complete-zsh > ~/.zsh/functions/_rg
      } &!
    fi

    if ! [[ -e "${XDG_DATA_HOME}/man/man1/rg.1"(#qN.mh+24) ]]; then
      {
        rm -f "${XDG_DATA_HOME}/man/man1/rg.1"
        command rg --generate=man > "${XDG_DATA_HOME}/man/man1/rg.1"
      } &!
    fi
  )
fi
